# This module is executed by build.py and uses its HTML/figure helpers.
chapter('kmp-z-sp', 'КМП: Z-функция, sp′ и поиск подстроки')
p('<span class="chapter-lead">От совпадений внутри образца — к сдвигам при поиске. Основной пример — <b>abacaba</b>. Разберём не только формулы, но и то, почему после несовпадения можно сохранить часть работы.</span>')
parts.append('<div class="operation-index steps"><b>Маршрут по главе</b><ul>' + ''.join(
    f'<li><a href="#{key}">{title}</a></li>' for key, title in [
        ('kmp-terms','Префикс, суффикс и индексы'), ('kmp-z-values','Как устроена Z-функция'),
        ('kmp-z-window','Линейный Z-препроцессинг'), ('kmp-sp-prime','Зачем нужна sp′'),
        ('kmp-z-to-sp','Переход от Z к sp′'), ('kmp-search','Поиск и откаты'),
        ('kmp-interactive','Пошаговый тренажёр'), ('kmp-realtime','КМП реального времени'),
        ('kmp-checks','Проверки и ошибки')]) + '</ul></div>')

def kh(key, title):
    parts.append(f'<h3 id="{key}">{title}</h3>')

def strip_diagram(title, rows, note_text):
    # rows: (label, text, horizontal shift in cells, highlighted positions).
    width = 960
    height = 72 + 58 * len(rows)
    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-label="{E(title)}"><title>{E(title)}</title>']
    for row, (label, text, shift, hot) in enumerate(rows):
        y = 22 + row * 58
        svg.append(f'<text x="15" y="{y+25}" font-family="Arial,sans-serif" font-size="17" fill="#263c3c">{E(label)}</text>')
        for index, char in enumerate(text):
            x = 230 + (index + shift) * 48
            fill = '#dcfce7' if index in hot else '#f3f5f4'
            svg.append(f'<rect x="{x}" y="{y}" width="43" height="38" rx="6" fill="{fill}" stroke="#64748b"/><text x="{x+21}" y="{y+25}" text-anchor="middle" font-family="monospace" font-size="21" fill="#172033">{E(char)}</text>')
    svg.append(f'<text x="15" y="{height-15}" font-family="Arial,sans-serif" font-size="16" fill="#475569">{E(note_text)}</text></svg>')
    drawing = ''.join(svg)
    svgs.append((title, drawing))
    parts.append(f'<figure>{drawing}<figcaption>{len(svgs)}. {title}</figcaption></figure>')

kh('kmp-terms', '1. Что ищем и как читаем индексы')
p('Даны текст T длины n и образец P длины m. Ищем все начала вхождений P в T, включая перекрывающиеся. Для текста abacabacaba образец abacaba встречается с позиций 0 и 4. Один участок текста может принадлежать сразу двум вхождениям.')
note('<b>Все индексы здесь с нуля.</b> P[0:k) — первые k символов, правая граница не включается. Позиции образца abacaba: 0:a, 1:b, 2:a, 3:c, 4:a, 5:b, 6:a. Переменная q означает количество совпавших символов, поэтому следующий ожидаемый символ — P[q].')
p('Префикс — начало строки, суффикс — её окончание. Оба читаются слева направо. Суффикс не переворачивается: последние два символа abacaba — ba, а не ab. Собственная граница — одинаковые префикс и суффикс, которые короче всей рассматриваемой строки.')
table(['Длина','Префикс abacaba','Суффикс abacaba','Результат'],[
    ['1','a','a','Граница'],['2','ab','ba','Не равны; ba не переворачиваем'],
    ['3','aba','aba','Самая длинная собственная граница'],['4','abac','caba','Не равны'],
    ['5','abaca','acaba','Не равны'],['6','abacab','bacaba','Не равны'],
    ['7','abacaba','abacaba','Вся строка: исключена определением']])
strip_diagram('Начало aba и окончание aba совпадают без переворота',[
    ('Префикс длины 3','abacaba',0,{0,1,2}),
    ('Суффикс длины 3','abacaba',0,{4,5,6})], 'Зелёные фрагменты читаются слева направо: a → b → a.')
p('Обычная префикс-функция π[i], которую также обозначают sp[i], хранит длину самой длинной собственной границы P[0:i+1). Для abacaba она равна [0, 0, 1, 0, 1, 2, 3]. Например, π[4] = 1 относится к строке abaca, у которой граница a. Символы справа от позиции 4 при определении этой границы не участвуют.')

kh('kmp-z-values', '2. Z-функция: совпадения с началом образца')
p('Z[i] — длина самого длинного фрагмента, начинающегося в позиции i и совпадающего с началом P. Сравниваем P[0] с P[i], затем P[1] с P[i+1] и так далее до первого несовпадения или конца строки. Это не поиск границы всего префикса: начальная позиция совпадения здесь фиксирована, а длина определяется сравнением.')
note('<b>Договорённость о Z[0].</b> В этой главе Z[0] = m, поскольку вся строка совпадает с собой. Иногда пишут Z[0] = 0. Оба соглашения подходят: построение sp′ использует только позиции от 1 до m−1.')
table(['i','Суффикс от i','Проверка с началом abacaba','Z[i]'],[
    ['0','abacaba','Вся строка совпадает с собой','7'],
    ['1','bacaba','b ≠ a: совпадение не началось','0'],
    ['2','acaba','a = a, затем c ≠ b','1'],
    ['3','caba','c ≠ a','0'],
    ['4','aba','Совпало aba, достигнут конец строки','3'],
    ['5','ba','b ≠ a','0'],
    ['6','a','Совпал a, достигнут конец строки','1']])
strip_diagram('Z[4] = 3: фрагмент от позиции 4 совпадает с началом',[
    ('Образец P','abacaba',0,{4,5,6}), ('Начало P под ним','aba',4,{0,1,2})],
    'Начало совпадения — 4, длина — 3, последняя позиция — 4 + 3 − 1 = 6.')
p('Каждый положительный Z[i] задаёт Z-блок [i, i+Z[i]). Для abacaba непустые блоки начинаются в 2, 4 и 6. Блок от 4 заканчивается на позиции 6 включительно. Запомни разницу: i+Z[i] — граница справа, а i+Z[i]−1 — индекс последнего совпавшего символа.')

kh('kmp-z-window', '3. Как вычислить Z за O(m), а не сравнивать всё заново')
p('Храним окно [L,R), совпадающее с началом образца и имеющее самый дальний известный конец. Инвариант: P[L:R) = P[0:R−L). Окно может быть пустым. Правая граница исключена, поэтому внутри него находятся позиции i &lt; R.')
steps('Обработка очередной позиции i',[
    'Если i ≥ R, окно ничего не сообщает о совпадении от i. Начни с длины 0.',
    'Если i &lt; R, используй соответствующую позицию i−L в начале образца: начальная длина равна min(Z[i−L], R−i).',
    'Сравни следующие символы P[Z[i]] и P[i+Z[i]]. Пока они равны и правая позиция существует, увеличивай длину.',
    'Если i+Z[i] &gt; R, новое совпадение уходит дальше: замени окно на [i, i+Z[i]).',
    'Сохрани Z[i] и перейди к следующей позиции. Уже известные значения не пересчитывай.'])
p('Почему можно копировать Z[i−L]? Внутри окна строка повторяет начало P, поэтому относительное положение i−L переносит нас в уже изученный фрагмент. Но за R совпадение не доказано: поэтому копируем не больше R−i символов. Остальное проверяем явно.')
table(['i','Окно до шага','Начальная длина','Проверки','Z[i], окно после'],[
    ['1','[0,0)','0','b ≠ a','0; [1,1)'],
    ['2','[1,1)','0','a = a; c ≠ b','1; [2,3)'],
    ['3','[2,3)','0','c ≠ a','0; [2,3)'],
    ['4','[2,3)','0','a = a, b = b, a = a; конец','3; [4,7)'],
    ['5','[4,7)','min(Z[1],2) = 0','b ≠ a','0; [4,7)'],
    ['6','[4,7)','min(Z[2],1) = 1','Уже достигнут конец','1; [4,7)']])
p('Линейность получается за счёт правой границы: новые успешные сравнения за известным окном двигают R вправо, всего не более m раз. Если скопированное совпадение закончилось строго внутри окна, следующее сравнение обнаруживает известное несовпадение. Дополнительно на каждую позицию приходится не более одного неуспешного завершающего сравнения. Итого O(m) времени и O(m) памяти.')

kh('kmp-sp-prime', '4. Зачем после Z вводится sp′ — «эс-пэ штрих»')
p('Обычная граница позволяет сохранить часть совпавших символов. Но при несовпадении мы знаем ещё кое-что: текущий символ текста не равен ожидаемому символу образца. Если после отката снова ожидается ровно тот же символ, сравнение заранее обречено на неудачу. Сильная таблица sp′ пропускает такие границы.')
note('<b>Определение для i &lt; m−1.</b> sp′[i] — максимальная длина k собственной границы P[0:i+1), для которой P[k] ≠ P[i+1]. Если положительной длины с этим свойством нет, значение равно 0. Для последней позиции используем sp′[m−1] = π[m−1]: после полного совпадения нужно сохранить самую длинную собственную границу.')
p('Условие относится к символам <b>после</b> двух совпавших фрагментов. При длине границы k последний символ префикса имеет индекс k−1, а следующий — k. После суффикса, заканчивающегося в i, находится P[i+1]. Сравниваем именно P[k] и P[i+1], а не последние символы границы.')
table(['i','Префикс до i','Обычная граница','Символы после неё','π[i]','sp′[i]'],[
    ['0','a','Нет непустой','—','0','0'],['1','ab','Нет непустой','—','0','0'],
    ['2','aba','a, k = 1','P[1] = b, P[3] = c: различаются','1','1'],
    ['3','abac','Нет непустой','—','0','0'],
    ['4','abaca','a, k = 1','P[1] = b, P[5] = b: одинаковые','1','0'],
    ['5','abacab','ab, k = 2','P[2] = a, P[6] = a: одинаковые','2','0'],
    ['6','abacaba','aba, k = 3','Конец образца: сохраняем границу','3','3']])
p('Итак, для abacaba: <b>sp′ = [0, 0, 1, 0, 0, 0, 3]</b>. Она отличается от π = [0, 0, 1, 0, 1, 2, 3]. Обозначения sp и sp′ нельзя использовать как взаимозаменяемые.')
steps('Почему sp′[4] = 0, хотя π[4] = 1',[
    'В тексте уже совпало abaca. Следующим образец ожидает b, но текущий символ текста — другой.',
    'Обычный откат мог бы сохранить последнюю a как начало нового совпадения.',
    'Однако после начальной a образец опять ожидает b. Мы уже знаем, что текущий символ не b: повторная проверка бесполезна.',
    'Положительных подходящих границ больше нет. Сильный откат сразу переходит к состоянию 0 и проверяет тот же символ с P[0] = a.'])
strip_diagram('Граница a в abaca пропускается: после обеих a ожидается b',[
    ('Образец','abacaba',0,{4}), ('После отката к a','abacaba',4,{0})],
    'При несовпадении с b повторно ожидать b не нужно: sp′[4] = 0.')
p('Нулевое значение — договорённость «подходящей непустой границы нет». Оно не утверждает, что P[0] обязательно отличается от ожидавшегося символа. Поэтому обработка состояния 0 в поиске всё равно нужна.')

kh('kmp-z-to-sp', '5. Почему sp′ получается из концов Z-блоков')
p('Пусть j &gt; 0 и Z[j] = k &gt; 0. Совпадение P[0:k) = P[j:j+k) заканчивается в i = j+k−1. Значит, k — длина собственной границы префикса P[0:i+1).')
p('Если блок закончился до конца образца, то следующие символы различаются: иначе Z[j] можно было бы увеличить. Получаем P[k] ≠ P[i+1] — как раз дополнительное условие сильной границы. Если блок достиг конца образца, получаем обычную границу всего образца для продолжения после ответа.')
note('<b>Отличие от построения π.</b> Для sp′ записывается длина только на <b>конце максимального Z-блока</b>. Его внутренние позиции не заполняют убывающими длинами: совпадение там ещё продолжается, следовательно, следующие символы равны. Такое заполнение давало бы информацию для обычной π, а не sp′.')
steps('Построение sp′ за линейное время',[
    'Создай массив длины m, заполненный нулями.',
    'Перебирай начала j от m−1 вниз до 1. Позицию 0 не используй.',
    'Если Z[j] = 0, пропусти эту позицию.',
    'Иначе вычисли конечный индекс i = j + Z[j] − 1 и запиши sp′[i] = Z[j].',
    'Если ячейка уже заполнена, перезапиши её: при таком порядке новая длина будет больше.'])
p('Почему идём справа налево? Для фиксированного конца i длина равна i−j+1. Чем левее начало j, тем длиннее совпадение. Левое начало обрабатывается позже и оставляет максимальную длину. При проходе слева направо без максимума короткая граница могла бы затереть длинную.')
table(['j, справа налево','Z[j]','Конец i','Изменение','Массив sp′ после шага'],[
    ['6','1','6','sp′[6] = 1','[0,0,0,0,0,0,1]'],
    ['5','0','—','Пропуск','[0,0,0,0,0,0,1]'],
    ['4','3','6','sp′[6] = 3: заменяем 1','[0,0,0,0,0,0,3]'],
    ['3','0','—','Пропуск','[0,0,0,0,0,0,3]'],
    ['2','1','2','sp′[2] = 1','[0,0,1,0,0,0,3]'],
    ['1','0','—','Пропуск','[0,0,1,0,0,0,3]']])
p('Здесь один проход и постоянное число действий на позицию, поэтому преобразование занимает O(m) времени. Образец не перечитывается попарными сравнениями; вся информация уже есть в Z. При нулевой Z-ячейке лучше сразу делать пропуск, особенно если индексы беззнаковые: не вычисляй выражение с вычитанием единицы без необходимости.')

kh('kmp-search', '6. Как поиск использует sp′')
p('Храним i — позицию следующего символа текста, и q — длину уже совпавшего префикса. Пока q &lt; m, текст непосредственно перед i заканчивается на P[0:q). Следующая пара для сравнения — T[i] и P[q]. После сильного отката сохранённая часть тоже совпадает, хотя она не обязана быть самой длинной обычной границей: часть кандидатов намеренно пропущена.')
steps('Действия при сравнении',[
    'Если символы равны: увеличь i и q. Продолжай вправо.',
    'Если q стало равно m: сообщи начало i−m. Затем замени q на sp′[m−1]. Индекс i не меняется.',
    'При несовпадении и q &gt; 0: замени q на sp′[q−1]. Символ T[i] ещё не обработан: сравни его снова, теперь с новым P[q].',
    'При несовпадении и q = 0: увеличь только i. Подходящего начала на этой позиции нет.',
    'Когда i достигло длины текста, новых символов нет. Полное совпадение, завершившееся на последнем символе, должно быть зарегистрировано.'])
p('Почему q−1? Если совпало q символов, последняя совпавшая позиция образца имеет индекс q−1. Таблица sp′ привязана к этой последней позиции, а не к следующему ожидаемому символу.')
p('В терминах сдвига: при положительной длине q старое начало выравнивания равно i−q, новое — i−sp′[q−1]. Значит, образец сдвигается на q−sp′[q−1]. Индекс текста остаётся на месте. Например, при q = 3 и sp′[2] = 1 сдвиг равен 2.')

kh('kmp-walkthrough', '7. Полная трассировка: abacaba в ababacaba')
table(['i','T[i]','q до сравнения','Ожидаемый символ','Действие'],[
    ['0','a','0','P[0] = a','Совпало: i = 1, q = 1'],
    ['1','b','1','P[1] = b','Совпало: i = 2, q = 2'],
    ['2','a','2','P[2] = a','Совпало: i = 3, q = 3'],
    ['3','b','3','P[3] = c','Не совпало: q = sp′[2] = 1, i остаётся 3'],
    ['3','b','1','P[1] = b','Тот же b подошёл: i = 4, q = 2'],
    ['4','a','2','P[2] = a','Совпало: i = 5, q = 3'],
    ['5','c','3','P[3] = c','Совпало: i = 6, q = 4'],
    ['6','a','4','P[4] = a','Совпало: i = 7, q = 5'],
    ['7','b','5','P[5] = b','Совпало: i = 8, q = 6'],
    ['8','a','6','P[6] = a','i = 9, q = 7: ответ 9−7 = 2; затем q = 3']])
strip_diagram('После несовпадения c с b сохраняем последнюю a',[
    ('Текст','ababacaba',0,{2}), ('Старое выравнивание','abacaba',0,{0,1,2}),
    ('Новое выравнивание','abacaba',2,{0})],
    'Текущий индекс текста остаётся 3; образец сдвинулся с начала 0 на начало 2.')

kh('kmp-strong-benefit', '8. Где сильная таблица пропускает лишнее сравнение')
p('Пусть P = abacaba, T = abacac. Первые пять символов abaca совпали. На позиции текста 5 находится c, а образец ожидает b, поэтому возникает несовпадение при q = 5.')
table(['Таблица','Последовательность действий с текущим c','Почему'],[
    ['Обычная π','q: 5 → 1 → 0; затем сравнение с a','π[4] = 1 сохраняет a, но после неё ожидается тот же b'],
    ['Сильная sp′','q: 5 → 0; затем сравнение с a','sp′[4] = 0 сразу пропускает повторное сравнение с b']])
p('Ответы одинаковы: вхождения нет. Отличается число сравнений. Сильная таблица использует информацию о причине несовпадения, но сама по себе не превращает весь поиск в автомат с гарантированным постоянным временем на символ.')

kh('kmp-overlap', '9. Как не потерять перекрывающиеся вхождения')
p('Ищем abacaba в abacabacaba. Первое вхождение закончилось на позиции 6. Его окончание aba уже является началом следующего вхождения, поэтому после ответа сохраняется q = sp′[6] = 3. Следующий ожидаемый символ — P[3] = c, и он совпадает с T[7]. Далее совпадают a, b и a, второе вхождение заканчивается в позиции 10 и начинается в 4.')
strip_diagram('Вхождения с началами 0 и 4 используют общую часть aba',[
    ('Текст','abacabacaba',0,{4,5,6}), ('Первое вхождение','abacaba',0,{4,5,6}),
    ('Второе вхождение','abacaba',4,{0,1,2})],
    'После первого ответа сохраняем длину 3, а не сбрасываем её в ноль.')
p('Для последнего индекса образца нет P[m], поэтому условие различия следующих символов отдельно не проверяется. В соглашении этой главы конечная sp′ равна обычной границе всего образца. Так Z-блоки, достигшие правого края, дают правильный откат после ответа.')

kh('kmp-interactive', '10. Пошаговый тренажёр: один переход за раз')
p('Выбери готовый пример и переходи по событиям. Одно событие — одно сравнение, выдача ответа или завершение. При откате индекс текста не движется. Входные значения зафиксированы, чтобы сначала изучить три ключевых случая без лишних настроек.')
parts.append('''<div class="kmp-lab steps" id="kmp-lab">
<label for="kmp-example"><b>Пример</b></label>
<select id="kmp-example">
<option value="fallback">Откат: abacaba в ababacaba</option>
<option value="skip">Сильная граница: abacaba в abacac</option>
<option value="overlap">Перекрытия: abacaba в abacabacaba</option>
</select>
<p id="kmp-arrays"></p>
<div class="scroll"><div id="kmp-alignment"></div></div>
<p id="kmp-event" role="status" aria-live="polite"></p>
<p id="kmp-result"></p>
<div class="kmp-controls"><button type="button" id="kmp-prev">Назад</button><button type="button" id="kmp-next">Следующий шаг</button><button type="button" id="kmp-reset">В начало</button><span id="kmp-counter"></span></div>
<noscript>Для тренажёра нужен JavaScript. Полная таблица тех же переходов приведена выше и доступна без JavaScript.</noscript>
</div>''')

kh('kmp-correctness', '11. Почему такой поиск не пропускает вхождения')
p('После несовпадения новая попытка может использовать только префикс образца, совпадающий с суффиксом уже прочитанного фрагмента. Иначе она противоречила бы ранее установленным равенствам. Это объясняет необходимость границ.')
p('Из обычных границ можно исключить те, после которых ожидается тот же символ, что только что не подошёл. Ни одна из них не продолжится текущим символом текста. sp′ выбирает самую длинную из оставшихся границ; если она тоже не продолжилась, выполняется следующий сильный откат. При переходе к 0 проверяется возможность начать совпадение текущим символом.')
p('Каждый положительный откат уменьшает q: собственная граница короче совпавшего фрагмента. Поэтому поиск не зацикливается. При q = 0 несовпадение продвигает i. При совпадении i тоже увеличивается. Текст никогда не читается назад.')

kh('kmp-complexity', '12. Откуда берётся O(n + m)')
table(['Этап','Время','Дополнительные данные'],[
    ['Z-функция образца','O(m)','Массив Z и границы окна'],
    ['Преобразование Z → sp′','O(m)','Массив sp′'],
    ['Поиск по тексту','O(n)','Индексы i и q'],
    ['Сохранение z ответов','O(z) суммарно','O(z) памяти для списка']])
p('В поиске q растёт только при успешном сравнении, максимум на единицу за продвижение по тексту. Все откаты его уменьшают. Поэтому суммарное число уменьшений не превосходит суммарного роста. Неудача в нулевом состоянии сразу продвигает i. Итого число сравнений и откатов линейно по n, даже если один символ потребовал несколько действий.')
p('Для непустого образца z ≤ n, поэтому общая оценка с выдачей всех ответов остаётся O(n+m). Вспомогательная память без списка ответов — O(m). Если текст приходит порциями, можно сохранять i и q между порциями; подготовка образца от текста не зависит.')

kh('kmp-realtime', '13. КМП реального времени: что меняется')
p('Линейное время всего поиска не означает гарантированного O(1) на каждый символ. Даже сильная таблица допускает несколько откатов на одном входном символе. Например, у образца abacabad после совпавшего abacaba и прихода x, отсутствующего в образце, сильные откаты проходят через длины 7, 3, 1 и 0. Один символ всё ещё может требовать нескольких сравнений.')
p('Автомат заранее вычисляет итоговый переход для каждой пары «длина совпадения q, символ c». Во время поиска весь цикл откатов заменяется одним чтением go[q][c]. Класс для этого не нужен: таблица, состояние и один цикл по тексту могут находиться в обычной функции.')
steps('Построение полного автомата',[
    'Подготовь обычную π — напрямую или через Z. В этом объяснении используем именно её, чтобы применить правило перехода через самую длинную обычную границу.',
    'Создай состояния 0…m и столбцы для всех символов алфавита.',
    'Для состояния 0 переход по P[0] ведёт в 1, остальные — в 0.',
    'Для состояния q &gt; 0 скопируй строку π[q−1]. Если q &lt; m, переход по P[q] замени на q+1.',
    'Строка m копируется с π[m−1] без обращения к P[m]. В поиске состояние m означает найденное вхождение и сохраняется до следующего перехода.'])
p('Если используется байтовый алфавит из 256 значений, столбец определяется приведением к unsigned char. Предобработка и память стоят O(mσ), каждый переход — O(1) в худшем случае при прямом доступе к столбцу. При 4 байтах на состояние строка из 256 переходов занимает 1024 байта. Обычный КМП экономнее по памяти.')
p('Гарантия на переход не включает выделение памяти под очередной ответ, запись на диск или работу пользовательского обработчика. Для строгой задержки эти действия рассматриваются отдельно. Вычисление sp′ улучшает откаты, а таблица автомата устраняет их из обработки текста — это разные уровни подготовки.')

kh('kmp-checks', '14. Что определить перед реализацией')
steps('Контракт самостоятельной реализации',[
    'Выбери единицу последовательности: для C++ string это байты, а не обязательно видимые буквы Unicode. Позиции ответа тогда тоже байтовые.',
    'Определи поведение пустого образца: можно запретить его явно либо выдавать все n+1 границ текста. Не обращайся к sp′[m−1], если m = 0.',
    'Реши, нужны ли все вхождения и перекрытия. Здесь нужны все.',
    'Зафиксируй Z[0], индексацию с нуля и полуоткрытое окно [L,R). Не смешивай формулы для включённой и исключённой правой границы.',
    'Сначала отдельно проверь Z, затем sp′ по определению, и только потом поиск. Для поиска используй независимый наивный эталон.'])
table(['Ошибка','Последствие','Правильная мысль'],[
    ['Переворачивать суффикс','Ищется другое свойство строки','И начало, и конец читаются слева направо'],
    ['Заполнять внутренние позиции Z-блока для sp′','Получается другая таблица','sp′ получает запись на конце максимального блока'],
    ['Перебирать j слева направо с обычным присваиванием','Короткая граница затирает длинную','Идти справа налево либо явно выбирать максимум'],
    ['Откатываться через sp′[q]','Сдвиг на один индекс в таблице','При совпавшей длине q последний индекс — q−1'],
    ['Продвигать i при положительном откате','Пропускается возможное продолжение','Снова проверить тот же символ текста'],
    ['Сбрасывать q в 0 после ответа','Теряются перекрытия','Сохранить sp′[m−1]'],
    ['Принимать сильный КМП за автомат реального времени','Неверная гарантия задержки','sp′ уменьшает сравнения, но допускает цепочку откатов']])

kh('kmp-test-cases', '15. Примеры для проверки')
table(['Текст','Образец','Начала вхождений','Что проверяет'],[
    ['ababacaba','abacaba','[2]','Откат с повторной проверкой b'],
    ['abacabacaba','abacaba','[0,4]','Перекрытие aba'],
    ['abacac','abacaba','[]','Пропуск бесполезной границы'],
    ['aaaaa','aaa','[0,1,2]','Много перекрытий; sp′ = [0,0,2]'],
    ['abcabc','abc','[0,3]','Соседние вхождения'],
    ['baaa','a','[1,2,3]','Образец длины 1'],
    ['Пустой','a','[]','Пустой текст'],
    ['ab','abacaba','[]','Образец длиннее текста'],
    ['abacaba','abacaba','[0]','Ответ на самом конце текста']])
quiz('Почему у abaca есть граница a, но sp′[4] равна 0?', 'После префикса a и после суффикса a в образце стоит b. При несовпадении с b такой откат немедленно повторил бы заведомо неуспешное сравнение. Обычная π[4] равна 1, а сильная sp′[4] — 0.')
quiz('Почему Z[4] = 3 записывается в sp′[6], а не в sp′[4]?', 'Z привязана к началу совпадения, sp′ — к его концу. Последний индекс равен 4+3−1 = 6.')
quiz('Почему короткое совпадение Z[6] = 1 не портит sp′[6] = 3?', 'Проход идёт справа налево: сначала записывается 1 от начала 6, затем 3 от начала 4. Более длинный кандидат остаётся последним.')
quiz('При q = 3 возникло несовпадение. Что меняется?', 'Заменяется q на sp′[2], для abacaba это 1. Позиция текста i остаётся прежней; её символ сравнивается с P[1].')
quiz('Нужен ли класс для КМП реального времени?', 'Нет. Таблицу переходов и текущее состояние можно хранить локально в обычной функции. Реальное время означает ограниченную стоимость перехода после подготовки, а не способ организации C++-кода.')
p('<b>Порядок подготовки к коду.</b> Вручную получи Z для abacaba, затем перенеси концы блоков в sp′. Объясни различие π[4] и sp′[4]. Выполни три примера тренажёра без подсказок. После этого реализация сводится к точному переводу уже понятных переходов в операции над индексами.')
p('Терминология Z-препроцессинга и сильных границ соответствует изложению Дэна Гасфилда в <a href="https://dmice.ohsu.edu/bedricks/courses/cs655/pdf/readings/gusfield_chap_1_2.pdf">Algorithms on Strings, Trees, and Sequences, главы 1–2</a>. Индексация и все трассировки здесь приведены с нуля. В исходниках DA-samples/4/kmp.hpp используется другая подготовка: обычная префикс-функция, вычисляемая напрямую, и завершающий символ $.')
end()
